vyVar = vy(i)+ay*dt;
yVar = y(i) + vy(i)*dt;

if (yVar <= 0)                 % => hit the floor with dt time resolution
% ——————————————————————————————— calculate Euler's method w/ a smaller dt
tVar = t;
    while(1)
    vy(i) = vy(i) + ay*dtw;
    yVar = y(i) + vy(i)*dtw;
        if(yVar <= 0)
            break;
        end
    vy(i) = vyVar;
    y(i) = yVar;
    tVar = tVar + dtw;
