Exolain js code // bridges prepares and returns Bridges data fieldset
export const bridges = (object => {

	//bridge fieldset
	const bridge = createFieldset.call({
		legend: 'Bridge Configuration Data',
		class: 'common',
	})

	//create port fieldset
	const port = {
		legend: 'Choose TnPort',
		class: 'common',
		name: 'port',
		default: object.TnPort,
		rows: object.Ports,
		display: 'grid',
		width: '50%',
	}.createFieldsetSelect()
	const selector = port.querySelector('select')
	selector.addEventListener('change', (evnt) => {
		object.TnPort = evnt.target.value
	})

	//create checkbox
	const box = {
		id: 'bridge',
		legend: 'Choose required bridges',
		class: 'common',
		name: 'bridge',
		rows: Object.keys(object.Vlans),
		display: 'grid'
	}.createFieldsetCheckbox()
	const checks = box.querySelectorAll('input[type="checkbox"]')
	checks.forEach(check => {
		check.addEventListener('change', (evnt) => {
			const key = evnt.target.value
			const row = box.querySelector(`#${key}`)
			let input = row.querySelector('input[type="text"]')
			if (input != undefined) {
				object.Vlans[key]['Vlan'] = ''
				input.remove()
				return box
			}
			input = {
				name: key,
				maxLen: 4,
				size: 4,
				pattern: '[0-9]+',
				placeholder: '3-4 digits Vlan number',
				title: '3-4 digits Vlan number required',
			}.createInputText()
			input.classList.add('pop-up')
			input.addEventListener('change', (evnt) => {
				object.Vlans[key]['Vlan'] = parseInt(evnt.target.value)
			})
			row.appendChild(input)	
		})
	})

	//return
	bridge.appendChild(box)
	bridge.appendChild(port)
	return bridge
})

