class Student extends Person {
private String studentId;

public Student(String first_name, String last_name, String studentId) {
super(first_name, last_name);
this.studentId = studentId;
}

public Student(Person person, String studentId) {
super(person.first_name, person.last_name);
this.studentId = studentId;
}

public void print() {
System.out.println("Student ID: " + studentId);
System.out.println("Student Name: " + super.first_name + " " + super.last_name);
}
}

