const targetWidth = 2048;
const targetHeight = 480;
const minDimension = 16;
const maxDimension = 2048;
const multipleOf = 8;

let width = parseFloat(xxxInput.value);
let height = parseFloat(yyyInput.value);



function recalculateDimensions() {
  // Parse the input values and check for validity
  const newWidth = parseFloat(xxxInput.value);
  const newHeight = parseFloat(yyyInput.value);

  if (isNaN(newWidth) || isNaN(newHeight)) {
    // Display an error message or handle the error case accordingly
    console.error('Invalid input. Please enter valid numerical values.');
    return;
  }

  // Update width and height only if the new values are valid
  width = newWidth;
  height = newHeight;

  // Calculate the total pixels based on width and height
  const totalPixels = width * height;

  // Adjust width and height to meet the total pixels dimension
  if (totalPixels > targetWidth * targetHeight) {
    const scaleFactor = Math.sqrt((targetWidth * targetHeight) / totalPixels);
    width = Math.floor(width * scaleFactor);
    height = Math.floor(height * scaleFactor);
  }

  // Ensure the adjusted width and height are within the allowed range
  width = Math.max(minDimension, Math.min(maxDimension, width));
  height = Math.max(minDimension, Math.min(maxDimension, height));

  // Calculate the nearest divisible by 8 width and height values
  const roundedWidth = Math.round(width / multipleOf) * multipleOf;
  const roundedHeight = Math.round(height / multipleOf) * multipleOf;

  // Update the input values with the rounded values
  xxxInput.value = roundedWidth;
  yyyInput.value = roundedHeight;
}

// Update the width and height values when the inputs change
xxxInput.addEventListener('change', function() {
  width = parseFloat(xxxInput.value);
  recalculateDimensions();
});

yyyInput.addEventListener('change', function() {
  height = parseFloat(yyyInput.value);
