M = 10;      %子脉冲数
dfs = 7e6;  %脉内跳频间隔
Bs = 5e6;   %子脉冲带宽
tp = 4e-6;  %子脉冲脉宽
k = Bs/tp;  %调频率
fs = 80e6;  %采样率
Ts=1/fs;    %采样间隔

N  = 1;     %脉冲数 
f0 = 14e9;  %信号载频
df = 80e6;   %脉间跳频间隔
Tr = 100e-6; %脉冲重复间隔
c = 3e8;
lambda = c/f0;
%目标参数
Targetnum = 1;
Trange =10e3;
Tvelocity = 400;
%干扰参数
Jrange =10e3-600;
Jvelocity = 400;
JSR = 20; %信干比
%% 发射信号仿真
N1 = round(tp/Ts); %一个子脉冲对应的采样点
N2 = round(Tr/Ts); %脉冲重复间隔对应的采样点   

sr=[];
sr_echo=[];
 a  = randperm(100)-1;  %脉间编码，0~63随机排序
for m = 1 : N
    b  = randperm(M)-1;%脉内编码，0~3随机排序
    % b=[1,0,2,3];
    for i = 1 : M
        t1 =((i-1)*N1:N1-1+(i-1)*N1)*Ts;
        %t=(0:N1-1)*Ts;
        xt = exp(1i*pi*k*(t1-(i-1)*tp).^2).*exp(1i*2*pi*b(i)*dfs*t1);

           % .*exp(1i*2*pi*(f0+a(m)*df)*(t1+(m-1)*Tr));
        % xt = cos(pi*k*t1.^2).*cos(2*pi*b(i)*dfs*t1).*cos(2*pi*(f0+a(m)*df)*(t1+(m-1)*Tr));
       NR = round((2*Trange/c)/Ts);
       sr_echo(:,NR+(i-1)*N1:NR+i*N1-1) = xt; 
        sr = [sr xt];
    end
    sr = [sr zeros(1,2*N2-N1)];
    sr_echo= [sr_echo zeros(1,2*N2-length(sr_echo))];
end

